using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 玩家管理器 (持久化单例) — 负责动态生成 Player 并跨场景保留。
///
/// 通过 [RuntimeInitializeOnLoadMethod] 在首个场景加载前自动创建，
/// 通过 SceneManager.sceneLoaded 事件在每次场景加载时检测：
/// - 场景中有 Player（Tag="Player"）→ 标记 DontDestroyOnLoad 保留
/// - 场景中无 Player → 从 Player 预制体动态生成
///
/// 依赖: 项目中存在 Tag="Player" 的 Player 预制体 (Assets/Prefab/Player.prefab)
/// 被 MapManager / EnemyCore 通过 GameObject.FindGameObjectWithTag("Player") 自动发现
/// </summary>
public class PlayerManager : MonoBehaviour
{
    public static PlayerManager Instance { get; private set; }

    [Header("Player 预制体")]
    [SerializeField] private GameObject _playerPrefab;

    [Header("出生位置")]
    [SerializeField] private Vector3 _spawnPosition = Vector3.zero;

    /// <summary>场景加载后触发: 参数为 (Player GameObject)</summary>
    public event System.Action<GameObject> OnPlayerReady;

    /// <summary>当前 Player GameObject 引用</summary>
    public GameObject CurrentPlayer { get; private set; }

    // ==================== 生命周期 ====================

    /// <summary>
    /// 在首个场景加载前自动创建 PlayerManager GameObject。
    /// 确保在任何场景加载时 PlayerManager 都已在 DontDestroyOnLoad 中就绪。
    /// </summary>
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void AutoInitialize()
    {
        if (Instance != null) return;

        var go = new GameObject("[PlayerManager]");
        go.AddComponent<PlayerManager>();
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);

        // Editor: 自动查找 Player 预制体，免去手动配置
        // Build: 需将 Player.prefab 放入 Resources/ 目录
        if (_playerPrefab == null)
        {
            _playerPrefab = ResolvePlayerPrefab();
        }
    }

    private void OnEnable()
    {
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    // ==================== 场景加载回调 ====================

    /// <summary>每次场景加载后触发，确保场景中存在 Player</summary>
    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        // Start 场景: 销毁 Player 和统计数据
        if (scene.name == "Start")
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            DestroyStatistics();
            return;
        }

        // Result / Winning 结算场景: 销毁 Player，但保留统计数据供 UI 展示
        if (scene.name == "Result" || scene.name == "Winning")
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            return;
        }

        // === 游戏场景 ===

        // 确保 GameStatistics 存在
        if (GameStatistics.Instance == null)
        {
            var statsGo = new GameObject("[GameStatistics]");
            statsGo.AddComponent<GameStatistics>();
        }

        var player = GameObject.FindGameObjectWithTag("Player");

        // 已存在 Player —— 优先复用（可能是场景中手动放置的，或是上一场景保留的）
        if (player != null)
        {
            // 首次注册: 标记为 DontDestroyOnLoad 以便跨场景保留
            if (player != CurrentPlayer)
            {
                CurrentPlayer = player;
                DontDestroyOnLoad(player);

                // 跨场景复用时不保留当前位置，重置
                player.transform.position = Vector3.zero;

#if UNITY_EDITOR
                Debug.Log($"[PlayerManager] 复用场景中已有的 Player: '{player.name}', 位置={Vector3.zero}");
#endif
            }
            player.transform.position = Vector3.zero;
        }
        // 无 Player —— 从预制体动态生成
        else
        {
            if (_playerPrefab == null)
            {
                Debug.LogError("[PlayerManager] _playerPrefab 未配置！请在 Inspector 中指定 Player 预制体。");
                return;
            }

            var spawned = Instantiate(_playerPrefab, _spawnPosition, Quaternion.identity);
            spawned.name = "Player";
            DontDestroyOnLoad(spawned);
            CurrentPlayer = spawned;

#if UNITY_EDITOR
            Debug.Log($"[PlayerManager] 动态生成 Player，位置={spawned.transform.position}");
#endif
        }

        // 绑定 Player 到统计系统
        GameStatistics.Instance?.BindPlayer(CurrentPlayer);

        OnPlayerReady?.Invoke(CurrentPlayer);
    }

    /// <summary>销毁统计数据</summary>
    private static void DestroyStatistics()
    {
        if (GameStatistics.Instance != null)
        {
            if (Application.isPlaying)
                Destroy(GameStatistics.Instance.gameObject);
            else
                DestroyImmediate(GameStatistics.Instance.gameObject);
        }
    }

    // ==================== 辅助 ====================

    /// <summary>自动查找 Player 预制体引用</summary>
    private static GameObject ResolvePlayerPrefab()
    {
#if UNITY_EDITOR
        // Editor 模式: 通过 AssetDatabase 按路径加载
        var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Player.prefab");
        if (prefab != null)
        {
            Debug.Log("[PlayerManager] 已自动加载 Player 预制体: Assets/Prefab/Player.prefab");
            return prefab;
        }
        Debug.LogWarning("[PlayerManager] 未找到 Assets/Prefab/Player.prefab，请确认路径正确。");
#endif

        // Build 模式: 从 Resources 目录加载
        var resourcePrefab = Resources.Load<GameObject>("Player");
        if (resourcePrefab != null)
        {
            Debug.Log("[PlayerManager] 已从 Resources 加载 Player 预制体。");
            return resourcePrefab;
        }

        Debug.LogError(
            "[PlayerManager] 无法找到 Player 预制体！\n" +
            "  - Editor: 请确认 Assets/Prefab/Player.prefab 存在\n" +
            "  - Build: 请将 Player.prefab 放入任意 Resources/ 目录下");
        return null;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [Tooltip("每分钟射击次数，300 = 每秒5发")]
    [SerializeField] private float shotsPerMinute = 300f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => 60f / shotsPerMinute;
    public float ShotsPerMinute => shotsPerMinute;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        health -= damage;
        health = Mathf.Max(health, 0);

        // 弹出伤害数字（玩家受伤用红色）
        DamagePopup.Spawn(transform.position, damage, isPlayerDamage: true);

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- Buff 系统属性读写接口 ----------

    /// <summary>通过属性名字符串获取当前值（供 Buff 系统使用）</summary>
    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"      => maxHealth,
            "MoveSpeed"      => moveSpeed,
            "AttackStrength"  => attackStrength,
            "BulletSpeed"    => bulletSpeed,
            "ShotsPerMinute" => shotsPerMinute,
            "ColliderRadius" => colliderRadius,
            _                => throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'")
        };
    }

    /// <summary>通过属性名字符串设置值，自动触发 OnStatChanged（供 Buff 系统使用）</summary>
    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                maxHealth = Mathf.Max(value, 1f);
                break;
            case "MoveSpeed":
                moveSpeed = Mathf.Max(value, 0f);
                break;
            case "AttackStrength":
                attackStrength = Mathf.Max(value, 0f);
                break;
            case "BulletSpeed":
                bulletSpeed = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinute":
                shotsPerMinute = Mathf.Max(value, 0f);
                break;
            case "ColliderRadius":
                colliderRadius = Mathf.Max(value, 0.01f);
                break;
            default:
                throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shotsPerMinute = Mathf.Max(shotsPerMinute, 1f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    private Rigidbody2D _rb;
    private PlayerCombat _combat;
    private PlayerStats _stats;
    private Vector2 _moveInput;

    /// <summary>攻击输入委托，由 PlayerCombat 订阅</summary>
    public event System.Action OnAttackInput;

    /// <summary>输入是否被锁定 (房间切换期间)</summary>
    public bool InputLocked { get; set; }

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _combat = GetComponent<PlayerCombat>();
        _stats = GetComponent<PlayerStats>();

        if (_combat != null)
            OnAttackInput += _combat.TryShoot;

#if UNITY_EDITOR
        if (_rb == null)
            Debug.LogWarning("PlayerController: 未找到 Rigidbody2D 组件！");
        if (_combat == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerCombat 组件！");
        if (_stats == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerStats 组件！");
#endif
    }

    void Start()
    {
        if (_stats == null) return;

        CircleCollider2D circle = GetComponent<CircleCollider2D>();
        if (circle != null)
        {
            _stats.ColliderRadius = circle.radius * Mathf.Max(transform.localScale.x, transform.localScale.y);
        }

        // Start 时 MapManager.Instance 已经初始化 (Awake 时序保证)
        if (MapManager.Instance != null)
        {
            MapManager.Instance.OnRoomSwitchStarted += (f, t) => InputLocked = true;
            MapManager.Instance.OnRoomSwitchCompleted += (t) => InputLocked = false;
        }
    }

    void Update()
    {
        if (_stats != null && _stats.IsDead) return;
        if (InputLocked)
        {
            _moveInput = Vector2.zero;
            return;
        }

        float horizontal = Input.GetAxisRaw("Horizontal");
        float vertical = Input.GetAxisRaw("Vertical");
        _moveInput = new Vector2(horizontal, vertical);
        _moveInput = Vector2.ClampMagnitude(_moveInput, 1f);

        if (Input.GetMouseButton(0))
        {
            OnAttackInput?.Invoke();
        }
    }

    void FixedUpdate()
    {
        if (_rb == null || _stats == null) return;
        if (_stats.IsDead) return;
        if (InputLocked) return;

        // 使用 Rigidbody2D 物理驱动，墙壁碰撞由 Collider2D 处理
        _rb.velocity = _moveInput * _stats.MoveSpeed;
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace WenJian.UI
{
    /// <summary>
    /// Start 场景主菜单控制器 — 处理 Play / Exit 按钮
    /// </summary>
    public class StartMenuController : MonoBehaviour
    {
        [Header("按钮引用")]
        [SerializeField] private Button playButton;
        [SerializeField] private Button exitButton;

        [Header("场景名称")]
        [SerializeField] private string playSceneName = "yang";

        private void Start()
        {
            if (playButton != null)
                playButton.onClick.AddListener(OnPlayClicked);

            if (exitButton != null)
                exitButton.onClick.AddListener(OnExitClicked);
        }

        private void OnPlayClicked()
        {
            SceneManager.LoadScene(playSceneName);
        }

        private void OnExitClicked()
        {
#if UNITY_EDITOR
            UnityEditor.EditorApplication.isPlaying = false;
#else
            Application.Quit();
#endif
        }

#if UNITY_EDITOR
        [ContextMenu("Test: Play")]
        private void TestPlay() => OnPlayClicked();

        [ContextMenu("Test: Exit")]
        private void TestExit() => OnExitClicked();
#endif
    }
}

