using UnityEngine;

/// <summary>
/// 地图生成配置 — 全局地牢生成参数
/// </summary>
[CreateAssetMenu(fileName = "MapConfig", menuName = "Map/Map Config")]
public class MapConfig : ScriptableObject
{
    [Header("随机种子")]
    [Tooltip("是否使用随机种子")]
    public bool useRandomSeed = true;

    [Tooltip("固定种子 (useRandomSeed=false 时生效)")]
    public int seed;

    [Header("房间数量")]
    [Tooltip("普通战斗房间数量")]
    public int normalRoomCount = 6;

    [Tooltip("宝藏房间数量")]
    public int treasureRoomCount = 1;

    [Tooltip("商店房间数量")]
    public int shopRoomCount = 1;

    [Header("最终房间")]
    [Tooltip("是否有 Boss 房间。true=Boss, false=Exit (二选一)")]
    public bool hasBoss = true;

    [Tooltip("Boss 房间数量 (hasBoss=true 时生效)")]
    public int bossRoomCount = 1;

    /// <summary>总房间数 (Start + 普通/宝藏/商店 + 最终Boss或Exit + 隐藏房)</summary>
    public int TotalRooms => normalRoomCount + treasureRoomCount + shopRoomCount + (hasBoss ? bossRoomCount : 1) + hiddenRoomCount + 1; // +1 for Start

    [Header("各类型可选房间预制体池")]
    [Tooltip("普通房间池")]
    public RoomConfig[] normalRoomPool;

    [Tooltip("宝藏房间池")]
    public RoomConfig[] treasureRoomPool;

    [Tooltip("Boss 房间池")]
    public RoomConfig[] bossRoomPool;

    [Tooltip("商店房间池")]
    public RoomConfig[] shopRoomPool;

    [Tooltip("隐藏房间池")]
    public RoomConfig[] hiddenRoomPool;

    [Tooltip("隐藏房数量")]
    public int hiddenRoomCount = 1;

    [Tooltip("起始房间 (固定)")]
    public RoomConfig startRoom;

    [Tooltip("出口房间 (固定)")]
    public RoomConfig exitRoom;

    [Header("关卡推进")]
    [Tooltip("下一层出口预制体 (须挂载 NextLevelExit 脚本)")]
    public GameObject nextLevelExitPrefab;

    [Tooltip("Boss/Exit 房间清空后跳转的场景名")]
    public string nextSceneName;

    [Header("布局参数")]
    [Tooltip("房间间距 (两房间之间的额外间距)")]
    public float roomSpacing = 0.5f;

    /// <summary>根据房间类型获取可选房间池</summary>
    public RoomConfig[] GetPoolForType(RoomType type)
    {
        return type switch
        {
            RoomType.Normal => normalRoomPool,
            RoomType.Treasure => treasureRoomPool,
            RoomType.Boss => bossRoomPool,
            RoomType.Shop => shopRoomPool,
            RoomType.Hidden => hiddenRoomPool,
            _ => null
        };
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间配置 — 定义某一类房间的通用参数 + 多个可选预制体变体
/// </summary>
[CreateAssetMenu(fileName = "RoomConfig", menuName = "Map/Room Config")]
public class RoomConfig : ScriptableObject
{
    [Header("基础信息")]
    [Tooltip("房间类型")]
    public RoomType roomType;

    [Tooltip("可选房间预制体列表 (生成时随机选取一个)")]
    public GameObject[] roomPrefabs;

    [Tooltip("难度等级 (影响怪物属性缩放等)")]
    public int difficultyLevel = 1;

    [Header("连接点 — 该房间有哪些方向的门")]
    public bool hasTopDoor;
    public bool hasBottomDoor;
    public bool hasLeftDoor;
    public bool hasRightDoor;

    [Header("房间尺寸 (世界单位，用于摄像机边界和布局计算)")]
    public Vector2 roomSize = new Vector2(20f, 12f);

    [Header("门在房间内的本地坐标偏移")]
    public Vector2 topDoorOffset = new Vector2(0f, 6.5f);
    public Vector2 bottomDoorOffset = new Vector2(0f, -6.5f);
    public Vector2 leftDoorOffset = new Vector2(-10.5f, 0f);
    public Vector2 rightDoorOffset = new Vector2(10.5f, 0f);

    [Header("怪物生成")]
    [Tooltip("可选怪物池")]
    public List<EnemySpawnEntry> enemyPool = new();

    [Tooltip("最少生成怪物数")]
    public int minEnemies = 1;

    [Tooltip("最多生成怪物数")]
    public int maxEnemies = 3;

    [Header("道具生成")]
    [Tooltip("可选道具池")]
    public List<GameObject> itemPool = new();

    [Tooltip("最少道具数")]
    public int minItems = 0;

    [Tooltip("最多道具数")]
    public int maxItems = 2;

    [Header("隐藏墙")]
    [Tooltip("隐藏墙血量 (需要攻击次数)，0=普通门")]
    public int hiddenWallHP = 0;

    /// <summary>获取指定方向门的本地坐标偏移</summary>
    public Vector2 GetDoorOffset(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => topDoorOffset,
            DoorDirection.Bottom => bottomDoorOffset,
            DoorDirection.Left => leftDoorOffset,
            DoorDirection.Right => rightDoorOffset,
            _ => Vector2.zero
        };
    }

    /// <summary>检查是否有指定方向的门</summary>
    public bool HasDoor(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => hasTopDoor,
            DoorDirection.Bottom => hasBottomDoor,
            DoorDirection.Left => hasLeftDoor,
            DoorDirection.Right => hasRightDoor,
            _ => false
        };
    }

    /// <summary>获取门的相反方向</summary>
    public static DoorDirection OppositeDir(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => DoorDirection.Bottom,
            DoorDirection.Bottom => DoorDirection.Top,
            DoorDirection.Left => DoorDirection.Right,
            DoorDirection.Right => DoorDirection.Left,
            _ => DoorDirection.Top
        };
    }

    /// <summary>从预制体池中随机选取一个。池为空时返回 null。</summary>
    public GameObject GetRandomPrefab()
    {
        if (roomPrefabs == null || roomPrefabs.Length == 0) return null;
        return roomPrefabs[Random.Range(0, roomPrefabs.Length)];
    }
}

