using UnityEngine;

/// <summary>
/// 玩家技能管理器，挂载在 Player GameObject 上。
/// 管理技能槽位、键位绑定、技能获取/升级/拓展。
/// </summary>
public class PlayerSkillManager : MonoBehaviour, ISkillCaster
{
    [Header("技能槽位")]
    [SerializeField] private List<SkillSlot> _slots = new()
    {
        new SkillSlot { keyBinding = KeyCode.Q },
        new SkillSlot { keyBinding = KeyCode.E },
        new SkillSlot { keyBinding = KeyCode.Z },
        new SkillSlot { keyBinding = KeyCode.X },
    };

    [Header("技能库")]
    [SerializeField] private SkillLibrary _skillLibrary;

    [Header("初始技能")]
    [Tooltip("游戏开始时自动装备的技能 ID（槽位 0~3，留空则不装备）")]
    [SerializeField] private string _initialSkillId0;
    [SerializeField] private string _initialSkillId1;
    [SerializeField] private string _initialSkillId2;
    [SerializeField] private string _initialSkillId3;

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;
    private PlayerStats _stats;

    public Vector2 GetTargetDirection()
    {
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;
        return (mouseWorldPos - transform.position).normalized;
    }

    public float GetAttackStrength() => _stats != null ? _stats.AttackStrength : 10f;

    public Projectile.OwnerType GetOwnerType() => Projectile.OwnerType.Player;

    // ---------- 委托 ----------
    /// <summary>技能释放事件：参数为 (槽位索引, 技能数据)</summary>
    public event System.Action<int, SkillData> OnSkillCast;
    /// <summary>技能升级事件</summary>
    public event System.Action<int, int> OnSkillUpgraded;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();
        EquipInitialSkills();
    }

    private void EquipInitialSkills()
    {
        var ids = new[] { _initialSkillId0, _initialSkillId1, _initialSkillId2, _initialSkillId3 };
        for (int i = 0; i < ids.Length; i++)
        {
            if (!string.IsNullOrEmpty(ids[i]))
                EquipSkill(i, ids[i]);
        }
    }

    void Update()
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            SkillSlot slot = _slots[i];
            slot.Skill?.TickCooldown(Time.deltaTime);

            if (slot.isUnlocked && Input.GetKeyDown(slot.keyBinding))
            {
                CastSkill(i);
            }
        }
    }

    // ---------- 释放 ----------
    private void CastSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return;
        SkillSlot slot = _slots[index];
        if (!slot.isUnlocked || slot.IsEmpty) return;

        Vector2 direction = GetTargetDirection();

        if (slot.TryCast(this, direction))
        {
            OnSkillCast?.Invoke(index, slot.Skill.Data);
        }
    }

    // ---------- 获取与装备 ----------
    /// <summary>从技能库获取技能并装备到第一个空槽</summary>
    public bool AcquireSkill(string skillId)
    {
        if (_skillLibrary == null) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        return instance != null && EquipToEmptySlot(instance);
    }

    /// <summary>装备技能到指定槽位</summary>
    public bool EquipSkill(int index, string skillId)
    {
        if (_skillLibrary == null) return false;
        if (index < 0 || index >= _slots.Count || !_slots[index].isUnlocked) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        if (instance == null) return false;

        _slots[index].Equip(instance);
        return true;
    }

    /// <summary>装备到第一个空槽</summary>
    public bool EquipToEmptySlot(SkillInstance skill)
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].isUnlocked && _slots[i].IsEmpty)
            {
                _slots[i].Equip(skill);
                return true;
            }
        }
        return false;
    }

    // ---------- 升级 ----------
    /// <summary>升级指定槽位技能</summary>
    public bool UpgradeSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return false;
        SkillSlot slot = _slots[index];
        if (slot.IsEmpty) return false;

        if (slot.Skill.TryUpgrade())
        {
            OnSkillUpgraded?.Invoke(index, slot.Skill.Level);
            return true;
        }
        return false;
    }

    // ---------- 槽位管理 ----------
    /// <summary>拓展技能槽数量</summary>
    public void ExpandSlots(int additionalSlots)
    {
        for (int i = 0; i < additionalSlots; i++)
        {
            _slots.Add(new SkillSlot { keyBinding = KeyCode.None, isUnlocked = true });
        }
    }

    /// <summary>解锁指定槽位</summary>
    public void UnlockSlot(int index)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].isUnlocked = true;
    }

    // ---------- 键位 ----------
    /// <summary>重新绑定槽位键位</summary>
    public void RebindKey(int index, KeyCode newKey)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].keyBinding = newKey;
    }

    /// <summary>获取槽位技能（供外部查询，如UI）</summary>
    public SkillInstance GetSkill(int index)
    {
        return (index >= 0 && index < _slots.Count) ? _slots[index].Skill : null;
    }

    /// <summary>查询槽位是否解锁（供 UI Controller 读取）</summary>
    public bool IsSlotUnlocked(int index)
    {
        return index >= 0 && index < _slots.Count && _slots[index].isUnlocked;
    }

    /// <summary>获取槽位绑定的快捷键（供 UI Controller 读取）</summary>
    public KeyCode GetKeyCode(int index)
    {
        if (index < 0 || index >= _slots.Count) return KeyCode.None;
        return _slots[index].keyBinding;
    }

    public int SlotCount => _slots.Count;
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 游戏统计单例 (DontDestroyOnLoad) — 追踪一局游戏的所有累计数据。
/// 
/// 生命周期:
///   Start 场景 → 销毁
///   游戏场景   → 创建/重置
///   Result 场景 → 保留 (供结算UI读取)
/// 
/// 订阅各系统事件，累计:
///   - 获得 / 消费的货币
///   - 获得的道具列表（含重复获取次数）
///   - 各类型房间的访问/清空数
///   - 各类型敌人的击杀数
/// </summary>
public class GameStatistics : MonoBehaviour
{
    public static GameStatistics Instance { get; private set; }

    // ========== 货币 ==========
    public int TotalCurrencyEarned { get; private set; }
    public int TotalCurrencySpent { get; private set; }

    // ========== 道具 ==========
    private readonly Dictionary<string, (ItemData data, int count)> _acquiredItems = new();
    /// <summary>累计获得的道具 (itemId → (ItemData, 获取次数))</summary>
    public IReadOnlyDictionary<string, (ItemData data, int count)> AcquiredItems => _acquiredItems;

    // ========== 房间 ==========
    private readonly Dictionary<RoomType, int> _roomsVisitedByType = new();
    private readonly Dictionary<RoomType, int> _roomsClearedByType = new();

    /// <summary>各房间类型的进入次数</summary>
    public IReadOnlyDictionary<RoomType, int> RoomsVisitedByType => _roomsVisitedByType;
    /// <summary>各房间类型的清空次数</summary>
    public IReadOnlyDictionary<RoomType, int> RoomsClearedByType => _roomsClearedByType;

    /// <summary>总进入房间数</summary>
    public int RoomsVisited { get; private set; }
    /// <summary>总清空房间数</summary>
    public int RoomsCleared { get; private set; }

    // ========== 击杀 ==========
    private readonly Dictionary<string, int> _enemiesKilled = new();
    /// <summary>敌人显示名 → 击杀数</summary>
    public IReadOnlyDictionary<string, int> EnemiesKilled => _enemiesKilled;

    // ========== 内部 ==========
    private CurrencyManager _boundCurrency;

    // ==================== 生命周期 ====================

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    private void OnEnable()
    {
        EnemyCore.OnAnyEnemyDied += OnEnemyDied;
    }

    private void OnDisable()
    {
        UnbindAll();
        EnemyCore.OnAnyEnemyDied -= OnEnemyDied;
    }

    private void OnDestroy()
    {
        UnbindAll();
        if (Instance == this)
            Instance = null;
    }

    // ==================== 绑定 / 解绑 ====================

    /// <summary>绑定 Player 身上的组件事件（货币/道具）</summary>
    public void BindPlayer(GameObject player)
    {
        if (player == null) return;

        var cm = player.GetComponent<CurrencyManager>();
        if (cm != null)
        {
            cm.OnCurrencyEarned += OnCurrencyEarned;
            cm.OnCurrencySpent += OnCurrencySpent;
            _boundCurrency = cm;
        }

        var im = player.GetComponent<ItemManager>();
        if (im != null)
        {
            im.OnItemAcquired += OnItemAcquired;
        }
    }

    /// <summary>解绑所有 Player 事件</summary>
    private void UnbindAll()
    {
        if (_boundCurrency != null)
        {
            _boundCurrency.OnCurrencyEarned -= OnCurrencyEarned;
            _boundCurrency.OnCurrencySpent -= OnCurrencySpent;
            _boundCurrency = null;
        }
    }

    // ==================== 事件回调 ====================

    private void OnCurrencyEarned(int amount)
    {
        TotalCurrencyEarned += amount;
    }

    private void OnCurrencySpent(int amount)
    {
        TotalCurrencySpent += amount;
    }

    private void OnItemAcquired(ItemData item)
    {
        if (item == null) return;

        string id = string.IsNullOrEmpty(item.itemId) ? item.name : item.itemId;
        if (_acquiredItems.TryGetValue(id, out var entry))
            _acquiredItems[id] = (entry.data, entry.count + 1);
        else
            _acquiredItems[id] = (item, 1);
    }

    private void OnEnemyDied(EnemyCore enemy)
    {
        if (enemy == null) return;

        string enemyName;
        if (enemy.config != null)
        {
            enemyName = !string.IsNullOrEmpty(enemy.config.displayName)
                ? enemy.config.displayName
                : enemy.config.name;
        }
        else
        {
            enemyName = enemy.name;
        }

        _enemiesKilled.TryGetValue(enemyName, out int count);
        _enemiesKilled[enemyName] = count + 1;
    }

    // ==================== 房间 ====================

    public void RecordRoomVisited(RoomType roomType)
    {
        RoomsVisited++;
        _roomsVisitedByType.TryGetValue(roomType, out int v);
        _roomsVisitedByType[roomType] = v + 1;
    }

    public void RecordRoomCleared(RoomType roomType)
    {
        RoomsCleared++;
        _roomsClearedByType.TryGetValue(roomType, out int v);
        _roomsClearedByType[roomType] = v + 1;
    }

    // ==================== 重置 ====================

    /// <summary>清空所有统计数据（新一局开始时调用）</summary>
    public void ResetAll()
    {
        TotalCurrencyEarned = 0;
        TotalCurrencySpent = 0;
        _acquiredItems.Clear();
        RoomsVisited = 0;
        RoomsCleared = 0;
        _roomsVisitedByType.Clear();
        _roomsClearedByType.Clear();
        _enemiesKilled.Clear();
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Buff 管理器 — 挂载到需要接收 Buff 的 GameObject 上。
/// 管理所有活跃 Buff 的生命周期（Apply / Tick / Remove）。
///
/// 用法: 挂载到 Player / Enemy Prefab 上，通过 ApplyBuff(BuffData) 添加 Buff。
/// </summary>
public class BuffManager : MonoBehaviour
{
    private readonly List<BuffInstance> _activeBuffs = new List<BuffInstance>();
    private readonly Dictionary<string, List<BuffInstance>> _buffDict = new Dictionary<string, List<BuffInstance>>();

    // 待移除队列 — 避免在迭代中修改集合
    private readonly List<BuffInstance> _pendingRemoval = new List<BuffInstance>();

    /// <summary>当前活跃 Buff 列表（只读）</summary>
    public IReadOnlyList<BuffInstance> ActiveBuffs => _activeBuffs;

    // ========== 事件 ==========

    /// <summary>Buff 被应用: (buff)</summary>
    public event Action<BuffInstance> OnBuffApplied;
    /// <summary>Buff 被移除: (buff)</summary>
    public event Action<BuffInstance> OnBuffRemoved;
    /// <summary>Buff 堆叠变化: (buff)</summary>
    public event Action<BuffInstance> OnBuffStackChanged;

    // ========== 核心方法 ==========

    /// <summary>
    /// 应用 Buff。如果同 ID Buff 已存在且可叠加，则尝试叠加；
    /// 否则创建新 BuffInstance。
    /// </summary>
    public BuffInstance ApplyBuff(BuffData data, GameObject caster = null)
    {
        if (data == null) return null;

        // 检查是否已有同 ID 的 Buff
        if (_buffDict.TryGetValue(data.buffId, out var existingList) && existingList.Count > 0)
        {
            var existing = existingList[0];
            if (data.stackable && existing.CurrentStacks < data.maxStacks)
            {
                existing.AddStack();
                OnBuffStackChanged?.Invoke(existing);
                return existing;
            }
            // 不可叠加且同 ID 已存在：刷新持续时间（如果非永久）
            if (!data.isPermanent)
                existing.AddStack(); // Refresh 模式下等同刷新
            return existing;
        }

        var buff = new BuffInstance(data, gameObject, caster);
        _activeBuffs.Add(buff);

        if (!_buffDict.ContainsKey(data.buffId))
            _buffDict[data.buffId] = new List<BuffInstance>();
        _buffDict[data.buffId].Add(buff);

        data.effect?.OnApply(gameObject, buff);
        OnBuffApplied?.Invoke(buff);
        return buff;
    }

    /// <summary>移除指定 Buff 实例</summary>
    public void RemoveBuff(BuffInstance buff)
    {
        if (buff == null || _pendingRemoval.Contains(buff)) return;
        _pendingRemoval.Add(buff);
    }

    /// <summary>移除指定 ID 的所有 Buff</summary>
    public void RemoveBuffById(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list))
        {
            for (int i = list.Count - 1; i >= 0; i--)
                RemoveBuff(list[i]);
        }
    }

    /// <summary>是否有指定 Buff</summary>
    public bool HasBuff(string buffId) =>
        _buffDict.TryGetValue(buffId, out var list) && list.Count > 0;

    /// <summary>获取指定 ID 的第一个 Buff 实例</summary>
    public BuffInstance GetBuff(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list) && list.Count > 0)
            return list[0];
        return null;
    }

    /// <summary>获取指定 ID 的所有 Buff 实例</summary>
    public IReadOnlyList<BuffInstance> GetBuffs(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list))
            return list;
        return System.Array.Empty<BuffInstance>();
    }

    /// <summary>获取 Buff 堆叠总数（所有同 ID Buff 的堆叠和）</summary>
    public int GetBuffStackCount(string buffId)
    {
        int total = 0;
        if (_buffDict.TryGetValue(buffId, out var list))
        {
            foreach (var b in list)
                total += b.CurrentStacks;
        }
        return total;
    }

    // ========== Unity 生命周期 ==========

    private void Update()
    {
        float dt = Time.deltaTime;

        // Tick 所有活跃 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            var buff = _activeBuffs[i];
            if (buff.IsActive)
                buff.Tick(dt);
        }

        // 处理过期 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            if (!_activeBuffs[i].IsActive || _activeBuffs[i].IsExpired)
                _pendingRemoval.Add(_activeBuffs[i]);
        }

        // 执行待移除
        ProcessRemovalQueue();
    }

    private void ProcessRemovalQueue()
    {
        for (int i = 0; i < _pendingRemoval.Count; i++)
        {
            var buff = _pendingRemoval[i];
            if (buff == null) continue;

            buff.IsActive = false;
            buff.Data.effect?.OnRemove(gameObject, buff);
            _activeBuffs.Remove(buff);

            if (_buffDict.TryGetValue(buff.Data.buffId, out var list))
            {
                list.Remove(buff);
                if (list.Count == 0)
                    _buffDict.Remove(buff.Data.buffId);
            }

            OnBuffRemoved?.Invoke(buff);
        }
        _pendingRemoval.Clear();
    }

    private void OnDestroy()
    {
        // 清理所有 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            var buff = _activeBuffs[i];
            buff.Data.effect?.OnRemove(gameObject, buff);
        }
        _activeBuffs.Clear();
        _buffDict.Clear();
    }
}

using System;
using UnityEngine;

/// <summary>
/// 技能运行时实例，持有 SkillData + 等级 + 冷却状态。
/// 通过 OnExecute 委托注入具体释放效果。
/// </summary>
public class SkillInstance
{
    public SkillData Data { get; private set; }
    public int Level { get; private set; } = 1;
    public int MaxLevel => Data.maxLevel;
    public bool IsMaxLevel => Level >= MaxLevel;
    public bool IsCoolingDown { get; private set; }

    private float _cooldownRemaining;

    /// <summary>剩余冷却秒数（供 UI 读取）</summary>
    public float CooldownRemaining => _cooldownRemaining;

    /// <summary>冷却进度 0~1，1=满冷却（刚释放），0=冷却完毕（供 UI 读取）</summary>
    public float CooldownPercent
    {
        get
        {
            float total = CurrentCooldown;
            return total > 0f ? Mathf.Clamp01(_cooldownRemaining / total) : 0f;
        }
    }

    /// <summary>当前等级冷却时间（每级减少10%）</summary>
    public float CurrentCooldown => Data.cooldown * (1f - (Level - 1) * 0.1f);

    /// <summary>当前等级伤害系数</summary>
    public float CurrentDamageMultiplier => Data.damageMultiplier * (1f + (Level - 1) * 0.15f);

    /// <summary>技能执行委托：参数为 (施法者, 目标方向)</summary>
    public event Action<ISkillCaster, Vector2> OnExecute;

    internal SkillInstance(SkillData data)
    {
        Data = data;
        Level = 1;
    }

    /// <summary>每帧驱动冷却</summary>
    public void TickCooldown(float deltaTime)
    {
        if (!IsCoolingDown) return;
        _cooldownRemaining -= deltaTime;
        if (_cooldownRemaining <= 0f)
        {
            IsCoolingDown = false;
            _cooldownRemaining = 0f;
        }
    }

    /// <summary>尝试释放技能，返回是否成功</summary>
    public bool TryCast(ISkillCaster caster, Vector2 targetDirection)
    {
        if (IsCoolingDown) return false;

        IsCoolingDown = true;
        _cooldownRemaining = CurrentCooldown;

        OnExecute?.Invoke(caster, targetDirection);
        return true;
    }

    /// <summary>升级技能，返回是否成功</summary>
    public bool TryUpgrade()
    {
        if (IsMaxLevel) return false;
        Level++;
        return true;
    }
}

using System;
using UnityEngine;

/// <summary>
/// 技能槽位：绑定键位 + 技能实例 + 解锁状态。
/// 在 Inspector 中可配置初始键位。
/// </summary>
[Serializable]
public class SkillSlot
{
    public KeyCode keyBinding = KeyCode.None;
    public bool isUnlocked = true;

    public SkillInstance Skill { get; private set; }
    public bool IsEmpty => Skill == null;

    public void Equip(SkillInstance skill) => Skill = skill;
    public void Unequip() => Skill = null;

    /// <summary>尝试释放槽位中的技能</summary>
    public bool TryCast(ISkillCaster caster, Vector2 direction)
    {
        return Skill != null && Skill.TryCast(caster, direction);
    }
}
